// Keep priced hotel rows, compare with the previous run (kept in workflow static data), emit drops.
const threshold = 0.10; // 10% cheaper than yesterday
const rows = $input.all().map(i => i.json).filter(r => r.type === 'hotel' && r.nightly);
const store = $getWorkflowStaticData('global'); store.prev = store.prev || {};
const drops = [];
for (const r of rows) {
  const key = `${r.entity_id}|${r.check_in}|${r.check_out}`; const prev = store.prev[key];
  if (prev && r.nightly <= prev * (1 - threshold)) drops.push({ name: r.name, from: prev, to: r.nightly, display: r.nightly_display, total: r.total_display, stay: `${r.check_in} → ${r.check_out}`, url: r.google_url });
  store.prev[key] = r.nightly;
}
return drops.length ? drops.map(d => ({ json: d })) : [{ json: { none: true, tracked: rows.length } }];
